<?= $this->extend('layouts/public') ?><?= $this->section('content') ?>
<section class="page-header"><div class="container narrow"><p class="eyebrow">Admissions</p><h1>Open admission programmes</h1><?php if ($cycle !== null): ?><p class="lead"><?= esc($cycle['title']) ?></p><?php endif ?></div></section>
<section class="section"><div class="container content-stack"><?php if ($programmes === []): ?><p>No programme is currently open for application.</p><?php else: ?><div class="card-grid"><?php foreach ($programmes as $programme): ?><article class="card"><h2><?= esc($programme['programme_name']) ?></h2><?php if (! empty($programme['entry_level_name'])): ?><p>Entry level: <?= esc($programme['entry_level_name']) ?></p><?php endif ?><?php if (! empty($programme['requirement_summary'])): ?><p><?= esc($programme['requirement_summary']) ?></p><?php endif ?><p><a href="<?= esc(public_site_url('admission_programme', [$programme['id']])) ?>">View requirements</a></p></article><?php endforeach ?></div><?php endif ?></div></section>
<?= $this->endSection() ?>
